create or replace function public.admin_grant_coins(_user uuid,_amount int) returns void language plpgsql security definer set search_path='' as $$ declare changed integer; begin if not private.is_admin() then raise exception 'not allowed'; end if; if _amount=0 or _amount < -1000000 or _amount > 1000000 then raise exception 'bad amount'; end if; insert into public.wallet_balances(user_id,coins,diamonds) values (_user,0,0) on conflict(user_id) do nothing; update public.wallet_balances set coins=coins+_amount,updated_at=now() where user_id=_user and coins+_amount>=0; get diagnostics changed=row_count; if changed=0 then raise exception 'insufficient balance or user missing'; end if; insert into public.wallet_transactions(user_id,kind,title,amount,currency,metadata) values (_user,'reward','Admin balance adjustment',_amount,'coins',jsonb_build_object('source','admin','actor',(select auth.uid()))); perform public.admin_write_audit('wallet_adjustment','user',_user::text,jsonb_build_object('delta',_amount)); end; $$;
create or replace function public.admin_set_vip(_user uuid,_vip int) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'not allowed'; end if; if _vip<0 or _vip>10 then raise exception 'bad vip level'; end if; update public.profiles set vip_level=_vip,updated_at=now() where id=_user; if not found then raise exception 'user not found'; end if; perform public.admin_write_audit('vip_changed','user',_user::text,jsonb_build_object('vip_level',_vip)); end; $$;
create or replace function public.admin_set_role(_user uuid,_role text,_grant boolean) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_super_admin() then raise exception 'only super admin'; end if; if _role not in ('admin','moderator','finance') then raise exception 'invalid role'; end if; if _grant then insert into public.admin_roles(user_id,role) values (_user,_role) on conflict(user_id) do update set role=excluded.role; else delete from public.admin_roles where user_id=_user and role=_role; end if; perform public.admin_write_audit('admin_role_changed','user',_user::text,jsonb_build_object('role',_role,'granted',_grant)); end; $$;
revoke execute on function public.is_admin(uuid),public.has_role(uuid,text),public.admin_stats(),public.admin_list_reports(text),public.admin_resolve_report(uuid,text,text),public.admin_delete_room(uuid),public.admin_delete_post(uuid),public.admin_list_users(text),public.admin_grant_coins(uuid,int),public.admin_set_vip(uuid,int),public.admin_set_role(uuid,text,boolean) from public,anon;
grant execute on function public.is_admin(uuid),public.has_role(uuid,text),public.admin_stats(),public.admin_list_reports(text),public.admin_resolve_report(uuid,text,text),public.admin_delete_room(uuid),public.admin_delete_post(uuid),public.admin_list_users(text),public.admin_grant_coins(uuid,int),public.admin_set_vip(uuid,int),public.admin_set_role(uuid,text,boolean) to authenticated;
